local config = {
  ui_story_32110401_1_dialog_content = "Aku punya kabar baik untuk diceritakan kepadamu.",
  ui_story_32110401_2_dialog_content = "Saya telah mengikuti program latihan khusus untuk meningkatkan akurasi serangan saya.",
  ui_story_32110401_3_dialog_content = "Dan kini akhirnya mulai terlihat hasilnya!",
  ui_story_32110401_4_dialog_content = "Tahu tidak, bahkan Nona Vice yang luar biasa pun memuji saya atas sejauh mana saya telah berkembang!",
  ui_story_32110401_5_dialog_content = "<anim type=Shake>B-B-Bullseye, Z-Zarya... Lihat... K-Kamu berhasil...</anim>",
  ui_story_32110401_6_dialog_content = "<anim type=Shake>J-J-Jelas ini berarti... k-k-kepresisian... bukan lagi m-m-masalah untukmu...</anim>",
  ui_story_32110401_7_dialog_content = "Benarkah? Rasanya tidak seperti aku benar-benar mengenai target...",
  ui_story_32110401_8_dialog_content = "Pokoknya, sepertinya itu berarti saya telah mencapai tujuan pelatihan khusus saya. Terima kasih banyak!",
  ui_story_32110401_9_dialog_content = "<anim type=Shake>Bagus... Semoga ini berarti akan ada lebih sedikit perabotan di Colossus yang perlu dicairkan... entah kenapa...</anim>",
  ui_story_32110401_10_dialog_content = "<size=50><anim type=Shake>Hatsyi!</anim></size>",
  ui_story_32110401_11_dialog_content = "\"Sang luar biasa Miss Vice...\"",
  ui_story_32110401_12_dialog_content = "Zarya, sepertinya kamu selalu mengagumi setiap kakak perempuan yang bisa diandalkan yang kamu temui...",
  ui_story_32110401_13_dialog_content = "Tidak ada orang lain di sekitar sini sekarang.",
  ui_story_32110401_14_dialog_content = "Apakah Anda ingin menggunakan kesempatan ini untuk melihat hasil latihan saya bersama Miss Vice?",
  ui_story_32110401_15_dialog_content = "Tentu.",
  ui_story_32110401_16_dialog_content = "Baru saja minum secangkir kopi panas dan aku siap! Jika kamu pikir kamu bisa membekukanku, ayo coba!",
  ui_story_32110401_17_dialog_content = "Uh... Sepertinya kamu tidak percaya bahwa aku telah mengalami peningkatan sama sekali.",
  ui_story_32110401_18_dialog_content = "Mengingat betapa kerasnya Nyonya Vice melatihku, aku HARUS membuatmu terkesan!",
  ui_story_32110401_19_dialog_content = "<color=#e8d9bb>Satu menit kemudian...</color>",
  ui_story_32110401_20_dialog_content = "Pertama... fokuskan pikiranku.",
  ui_story_32110401_21_dialog_content = "Lalu... kumpulkan Lumina dan kendalikan kekuatannya, seperti menggerakkan jari kelingkingku.",
  ui_story_32110401_22_dialog_content = "Akhirnya... tangkap saat yang tepat! Tuangkan kekuatan ke dalam satu aliran dan keluarkan!",
  ui_story_32110401_23_dialog_content = "Ruang tungguku! Kamu akan mengubahnya menjadi gua es!",
  ui_story_32110401_24_dialog_content = "Hah?",
  ui_story_32110401_25_dialog_content = "Aku sengaja mengincar pita yang terikat di kursi itu...",
  ui_story_32110401_26_dialog_content = "Kenapa seluruh ruangan ini jadi membeku?!",
  ui_story_32110401_27_dialog_content = "Mungkin kamu hanya tidak merasa seratus persen sekarang. Bagaimana kalau kita coba lagi lain kali saja...?",
  ui_story_32110401_28_dialog_content = "Tidak! Nona Vice mengatakan bahwa kontrol yang sempurna dicapai melalui latihan yang keras! Saya tidak akan mencari alasan untuk diri saya sendiri!",
  ui_story_32110401_29_dialog_content = "Tadi itu hanya kecelakaan saja. Ayo coba lagi di tempat lain!",
  ui_story_32110401_30_dialog_content = "Aku akan menggunakan kaleng kopi itu sebagai target kali ini! Aku pasti akan mengenainya!",
  ui_story_32110401_31_dialog_content = "Tunggu sebentar—",
  ui_story_32110401_32_dialog_content = "<size=45>Jangan yang itu! Itu bukan kopi biasa!</size>",
  ui_story_32110401_33_dialog_content = "Hya!",
  ui_story_32110401_34_dialog_content = "<size=45>Aaaaaah—!</size>",
  ui_story_32110401_35_dialog_content = "Itu adalah biji kopi super mahal yang saya minta Ms. Sheol untuk belikan untuk saya!",
  ui_story_32110401_36_dialog_content = "A-Aku bahkan belum sempat mencoba mereka... dan sekarang mereka semua... membeku...",
  ui_story_32110401_37_dialog_content = "Ah... M-Maaf!",
  ui_story_32110401_38_dialog_content = "Sigh... Semua usaha keras yang telah kulakukan beberapa hari ini... ternyata sia-sia.",
  ui_story_32110401_39_option_content = "(Berikan saran spesifik untuk Zarya)",
  ui_story_32110401_40_dialog_content = "Aku punya saran.",
  ui_story_32110401_41_dialog_content = "Sebelum meningkatkan akurasi, coba kurangi intensitas Lumina yang Anda keluarkan.",
  ui_story_32110401_42_dialog_content = "Itu pasti akan membuatnya lebih mudah untuk dikendalikan.",
  ui_story_32110401_43_option_content = "(Beritahu Zarya untuk minum lebih banyak air panas)",
  ui_story_32110401_44_dialog_content = "Lupakan semua itu untuk sekarang, cukup minum lebih banyak air panas dan hangatkan tubuh dulu.",
  ui_story_32110401_45_dialog_content = "Aku nggak mau... Kamu aja yang minum...",
  ui_story_32110401_46_dialog_content = "Jangan biarkan itu membuatmu sedih. Mari kita kesampingkan penargetan yang tepat untuk saat ini.",
  ui_story_32110401_47_dialog_content = "Mungkin jika kamu mulai dengan mengurangi kekuatan Lumina-mu, proses pengecoran bisa berjalan lebih lancar?",
  ui_story_32110401_48_dialog_content = "Hah?",
  ui_story_32110401_49_dialog_content = "Aku tidak bisa berjanji. Lagi pula, aku bukan seorang Aurorian.",
  ui_story_32110401_50_dialog_content = "Saya hanya berpikir, berdasarkan kemampuan saya sebagai Caelestite, rasanya seperti kamu menggunakan kekuatan yang terlalu besar.",
  ui_story_32110401_51_dialog_content = "Masuk akal jika kamu mungkin bisa mengendalikan kekuatanmu lebih baik jika mencoba melontarkan sedikit demi sedikit.",
  ui_story_32110401_52_dialog_content = "Setelah kamu menguasai langkah pertama ini, kamu dapat meningkatkan kekuatanmu secara bertahap hingga kamu dapat mengendalikannya sepenuhnya.",
  ui_story_32110401_53_dialog_content = "Itu memang solusi yang layak.",
  ui_story_32110401_54_dialog_content = "Tapi itu saja mungkin terlalu sederhana untuk kamu.",
  ui_story_32110401_55_dialog_content = "Hmm?",
  ui_story_32110401_56_dialog_content = "Aku penasaran apakah ada botol atau kaleng murah di sekitar sini...",
  ui_story_32110401_57_dialog_content = "Ah, menemukan satu. Ini seharusnya berhasil.",
  ui_story_32110401_58_dialog_content = "Kenapa kamu meletakkan botol itu di kepalamu?",
  ui_story_32110401_59_dialog_content = "Maksudmu bukan...?!",
  ui_story_32110401_60_dialog_content = "Zarya, aku ingin kamu memecahkan botol di kepala ku dengan esmu.",
  ui_story_32110401_61_dialog_content = "Hah? Kedengarannya sangat berbahaya!",
  ui_story_32110401_62_dialog_content = "Kalau aku tanpa sengaja memukulmu, kau akan...!",
  ui_story_32110401_63_dialog_content = "Kenapa kamu menganggap akan gagal sebelum mencoba?",
  ui_story_32110401_64_dialog_content = "Jangan khawatir. Bukan seperti ini pertama kalinya saya terkena Luminatics-mu. Pasti sekarang saya sudah memiliki sedikit ketahanan terhadap mereka.",
  ui_story_32110401_65_dialog_content = "Namun…",
  ui_story_32110401_66_dialog_content = "Tenang, Vice dan aku pernah melakukannya sebelumnya.",
  ui_story_32110401_67_dialog_content = "Jika kamu benar-benar khawatir, cukup gunakan kekuatan minimum yang bisa kamu kumpulkan untuk memukul botolnya.",
  ui_story_32110401_68_dialog_content = "Aku merasa kamu kesulitan mengendalikan kekuatanmu, benar? Mungkin karena kamu selalu berlatih dengan benda mati.",
  ui_story_32110401_69_dialog_content = "Juga, kamu selalu berlatih keterampilanmu di tempat yang sepi tanpa ada orang di sekitar.",
  ui_story_32110401_70_dialog_content = "Jadi, meskipun kamu melakukan kesalahan, kamu tidak perlu khawatir menyakiti siapa pun.",
  ui_story_32110401_71_dialog_content = "Benar... tapi apa yang salah dengan itu?",
  ui_story_32110401_72_dialog_content = "Pernahkah kamu mempertimbangkan bahwa, karena kamu selalu berlatih di area kosong, melawan target yang tak bernyawa...",
  ui_story_32110401_73_dialog_content = "Kamu pada dasarnya belum pernah harus fokus pada kekuatanmu sebelumnya.",
  ui_story_32110401_74_dialog_content = "!!!",
  ui_story_32110401_75_dialog_content = "Kali ini, kamu harus memukul botol di kepala saya...",
  ui_story_32110401_76_dialog_content = "Jika kamu tidak ingin aku terluka, maksudku.",
  ui_story_32110401_77_dialog_content = "PlayerName... itu sebenarnya sangat masuk akal.",
  ui_story_32110401_78_dialog_content = "Aku tidak bisa mundur sekarang!",
  ui_story_32110401_79_dialog_content = "(Aku tidak boleh membuat kesalahan kali ini... Aku tidak bisa mengacaukannya...)",
  ui_story_32110401_80_dialog_content = "(Seperti yang dikatakan oleh Miss Vice, blokir semua pikiran yang tidak perlu...)",
  ui_story_32110401_81_dialog_content = "(Hanya dengan menggabungkan kesadaranmu dengan kristal es, kau bisa berhasil...)",
  ui_story_32110401_82_dialog_content = "Dan ingat—gunakan daya seminimal mungkin...",
  ui_story_32110401_83_dialog_content = "Ayo beri warna pada salju!",
  ui_story_32110401_84_dialog_content = "Aku berhasil?!",
  ui_story_32110401_85_dialog_content = "Fiuh... Itu yang kupikirkan.",
  ui_story_32110401_86_dialog_content = "Zarya, bukan karena kamu kurang akurat—tapi kamu terlalu hebat dalam mengeluarkan kekuatanmu.",
  ui_story_32110401_87_dialog_content = "Apa artinya itu?",
  ui_story_32110401_88_dialog_content = "Ini berarti kamu tidak perlu khawatir untuk berusaha sebaik mungkin mengendalikan akurasi seperti yang dilakukan orang lain...",
  ui_story_32110401_89_dialog_content = "Tapi kamu memang perlu mengurangi kekuatanmu.",
  ui_story_32110401_90_dialog_content = "Ini seperti menuangkan kopi—tentu lebih mudah untuk menuangkan terlalu banyak kopi jika kalengmu memiliki bukaan yang lebar.",
  ui_story_32110401_91_dialog_content = "... Kekuatanku... memiliki celah yang luas?",
  ui_story_32110401_92_dialog_content = "Benar. Jadi, saya menyarankan Anda untuk menggunakan metode bertarung yang lebih cepat dan fleksibel saat berada dalam pertempuran.",
  ui_story_32110401_93_dialog_content = "Ini seharusnya dapat mengurangi peluang Anda untuk membuat kesalahan secara signifikan.",
  ui_story_32110401_94_dialog_content = "Hmm... Baiklah! Lain kali, akan kuingat ini dan mencoba melakukan hal yang sama lagi!",
  ui_story_32110401_95_dialog_content = "Wow, dan kamu bahkan tidak memberiku pembicaraan balik... Sepertinya bukan hanya kemampuanmu yang tumbuh hari ini—kepribadianmu juga tampaknya telah naik level...",
  ui_story_32110401_96_dialog_content = "Apa yang kamu katakan, PlayerName?",
  ui_story_32110401_97_dialog_content = "Maksud kamu... Aku sudah berkembang dalam cara lain, selain meningkatkan Luminatics-ku?",
  ui_story_32110401_98_dialog_content = "Erm, ya... Ada apa?",
  ui_story_32110401_99_dialog_content = "Jadi menurutmu sekarang aku lebih atau kurang menjadi seorang wanita yang dewasa, begitu?",
  ui_story_32110401_100_dialog_content = "Hah? Kenapa kamu mengatakan itu...? Aku tidak setuju, tidak...",
  ui_story_32110401_101_dialog_content = "Astaga! Apa yang kamu rencanakan?!",
  ui_story_32110401_102_dialog_content = "... Sayangku PlayerName...",
  ui_story_32110401_103_dialog_content = "Maukah kamu terus menjadi mitra latihan saya mulai sekarang?",
  ui_story_32110401_104_dialog_content = "Setelah semua, saat kamu menjadi sasaran latihanku, itulah saat pikiranku paling fokus...",
  ui_story_32110401_105_dialog_content = "Kumohooooon!",
  ui_story_32110401_106_dialog_content = "... Aku perlu memikirkannya!",
  ui_story_32110601_1_dialog_content = "(Ketika aku masih kecil, seringkali aku ditinggal sendirian di rumah.)",
  ui_story_32110601_2_dialog_content = "(Adikku harus pergi berpatroli dan tidak bisa menemani saya sepanjang waktu. Anak-anak lain juga tidak mau bermain dengan saya.)",
  ui_story_32110601_3_dialog_content = "(Saat itu, hanya ada beberapa hal dalam hidup yang bisa membuatku tersenyum, dan sebagian besar dari hal tersebut ada dalam buku cerita yang diberikan kakakku.)",
  ui_story_32110601_4_dialog_content = "(Buku itu berbicara tentang es di Northland—bagaimana es itu menjadi padat dan kuat, tetapi berubah menjadi air laut hangat ketika terpapar dunia luar.)",
  ui_story_32110601_5_dialog_content = "(Saudara perempuan saya juga dulu mengatakan bahwa kita bisa mengenakan baju renang dan mengunjungi negeri misteri yang menarik itu suatu hari nanti.)",
  ui_story_32110601_6_dialog_content = "(Tapi…)",
  ui_story_32110601_7_dialog_content = "<color=#e8d9bb>Bercipratan—</color>",
  ui_story_32110601_8_dialog_content = "Zarya?",
  ui_story_32110601_9_dialog_content = "<size=45>Zarya?</size>",
  ui_story_32110601_10_dialog_content = "Oh...",
  ui_story_32110601_11_dialog_content = "Apa kabar? Apakah ini tempat yang salah?",
  ui_story_32110601_12_dialog_content = "Bukankah ini lautan dari buku itu?",
  ui_story_32110601_13_dialog_content = "Bukan itu yang salah, PlayerName.",
  ui_story_32110601_14_dialog_content = "Hanya saja... ini adalah pertama kalinya aku melihat samudra tanpa es padat dengan mataku sendiri. Ini... menakjubkan.",
  ui_story_32110601_15_dialog_content = "Indah sekali…",
  ui_story_32110601_16_dialog_content = "Dunia luar sangat luas... Ini hanya sebagian kecil darinya.",
  ui_story_32110601_17_dialog_content = "Coba masukkan kakimu ke dalam air. Tidak ada yang bisa menyaingi sensasi ini.",
  ui_story_32110601_18_dialog_content = "Oh? Seperti ini?",
  ui_story_32110601_19_dialog_content = "Oh—",
  ui_story_32110601_20_dialog_content = "Apa pendapatmu? Rasanya enak, kan?",
  ui_story_32110601_21_dialog_content = "Ini tidak sama persis dengan mata air panas di Northland, tapi tetap sangat menyenangkan... Rasanya sangat hangat.",
  ui_story_32110601_22_dialog_content = "Dulu, saya sering mandi di mata air panas di Northland...",
  ui_story_32110601_23_dialog_content = "Angin di Northland sangat dingin dan menusuk. Adik perempuanku akan menolak untuk meninggalkan mata air panas yang nyaman.",
  ui_story_32110601_24_dialog_content = "Tapi di sini berbeda. Anginnya sangat lembut.",
  ui_story_32110601_25_dialog_content = "Bahkan jika saya berenang di bawah angin laut, saya tidak akan merasakan dingin yang menusuk.",
  ui_story_32110601_26_dialog_content = "Kalau saja dia...",
  ui_story_32110601_27_dialog_content = "<color=#e8d9bb>Tik-tik-tik—</color>",
  ui_story_32110601_28_dialog_content = "Hah? Tiba-tiba saja hujan turun!",
  ui_story_32110601_29_dialog_content = "Bahkan setelah aku meminjam semua boneka sunny ini dari Hiiro dan yang lainnya...",
  ui_story_32110601_30_dialog_content = "Bukankah lima puluh dari mereka sudah cukup?!",
  ui_story_32110601_31_dialog_content = "Mungkin... kita harus berhenti hari ini?",
  ui_story_32110601_32_dialog_content = "Lihat-lihat apa kau?",
  ui_story_32110601_33_dialog_content = "Hujan ini...",
  ui_story_32110601_34_dialog_content = "Air hujan di sini... sangat ringan dan tidak akan membeku...",
  ui_story_32110601_35_dialog_content = "Kamu akan masuk angin jika terus seperti ini.",
  ui_story_32110601_36_dialog_content = "Dan pakaian baru yang kamu kenakan hari ini akan basah kuyup.",
  ui_story_32110601_37_dialog_content = "Aku tidak akan sakit karena hujan hangat seperti ini.",
  ui_story_32110601_38_dialog_content = "Dibandingkan dengan peti es yang memenjarakan saya selama seratus tahun, hujan ini seperti belaian lembut alam.",
  ui_story_32110601_39_dialog_content = "Inilah yang aku bayangkan rasanya ketika peri dari buku cerita ku bergerak-gerakkan sayap mereka di atas wajahku.",
  ui_story_32110601_40_dialog_content = "Hei, sekarang kamu langsung duduk saja?",
  ui_story_32110601_41_dialog_content = "Sungguh segelintir...",
  ui_story_32110601_42_dialog_content = "<color=#e8d9bb>Hujan turun dengan pitter-patter...</color>",
  ui_story_32110601_43_dialog_content = "<color=#e8d9bb>Zarya duduk di atas batu, pakaiannya basah kuyup oleh hujan yang dingin.</color>",
  ui_story_32110601_44_dialog_content = "Hmm?",
  ui_story_32110601_45_dialog_content = "Fiuh, untunglah aku membawa payung...",
  ui_story_32110601_46_dialog_content = "PlayerName, kamu benar-benar tidak perlu khawatir tentang saya.",
  ui_story_32110601_47_dialog_content = "Aku nggak khawatir! Ini hanya...",
  ui_story_32110601_48_dialog_content = "... Uh, jika kamu masuk angin, No. 33 akan menyalahkan aku karena tidak merawatmu!",
  ui_story_32110601_49_dialog_content = "Pfft—",
  ui_story_32110601_50_dialog_content = "Jadi begitu, ya? Sungguh tidak jujur dari kamu...",
  ui_story_32110601_51_dialog_content = "Minggir sana! Jangan pikirkan sedetik pun bahwa aku seceroboh kamu...",
  ui_story_32110601_52_dialog_content = "Aku hanya merasa ada sesuatu yang sedang membebani pikiranmu.",
  ui_story_32110601_53_dialog_content = "Kamu merasa sedikit aneh sejak melihat samudra.",
  ui_story_32110601_54_dialog_content = "Maukah kamu ceritakan apa yang mengganggumu?",
  ui_story_32110601_55_dialog_content = "Seperti yang Anda tahu, cuaca di Northland sangat keras, untuk tidak mengatakan lebih.",
  ui_story_32110601_56_dialog_content = "Saat aku tumbuh besar, cuaca mendung seperti ini adalah pertanda bahwa hujan es segera akan datang.",
  ui_story_32110601_57_dialog_content = "Kakak saya akan segera pulang ke rumah untuk menghindari hujan es, dan bahkan ayah saya akan menunda sementara urusan bisnisnya.",
  ui_story_32110601_58_dialog_content = "Itu semua sudah lama sekali, tapi tetap saja, aku ingat suara menakutkan hujan es yang jatuh.",
  ui_story_32110601_59_dialog_content = "Kapanpun aku merasa takut, kakakku akan mengambil buku cerita dan menghiburku dengan kisah-kisah tentang dunia luar.",
  ui_story_32110601_60_dialog_content = "Dia akan mengelus kepalaku dan berbisik lembut di telingaku:",
  ui_story_32110601_61_dialog_content = "\"Zarya, kamu tahu tidak perlu takut pada hujan dan salju, kan? Ada dunia yang menakjubkan menunggu untuk kamu jelajahi di luar sana.\"",
  ui_story_32110601_62_dialog_content = "\"Ada tempat di mana laut tidak membeku, dan hujan lembut serta menenangkan.\"",
  ui_story_32110601_63_dialog_content = "\"Jika kita mendapat kesempatan, ayo kenakan pakaian renang kita dan berenang di surga eksotis yang indah suatu hari nanti.\"",
  ui_story_32110601_64_dialog_content = "Lalu, sekarang...",
  ui_story_32110601_65_dialog_content = "Saya di sini.",
  ui_story_32110601_66_dialog_content = "Di mana laut tak pernah membeku... mengenakan baju renangku...",
  ui_story_32110601_67_dialog_content = "Tapi tidak ada orang di sini untuk merayakan impian ini yang menjadi kenyataan bersamaku.",
  ui_story_32110601_68_dialog_content = "Apakah semua anggota keluarga Anda seberapa tertarik dengan dunia luar seperti Anda?",
  ui_story_32110601_69_dialog_content = "Saya pikir... mereka memang begitu.",
  ui_story_32110601_70_dialog_content = "Tentu saja, kakakku selalu ingin menunjukkan dunia luar kepadaku, tetapi pekerjaannya selalu menghalangi.",
  ui_story_32110601_71_dialog_content = "Ayahku juga tertarik dengan produk-produk asing.",
  ui_story_32110601_72_dialog_content = "Untuk ibuku... dia meninggal saat aku masih kecil, jadi sekarang aku hampir tidak bisa mengingatnya.",
  ui_story_32110601_73_dialog_content = "Tapi dia selalu dekat dengan ayahku, yang sering bepergian jauh, jadi aku berasumsi dia mungkin penasaran tentang dunia yang lebih luas.",
  ui_story_32110601_74_dialog_content = "Jadi, belumkah Anda menepati kesepakatan dengan mereka semua?",
  ui_story_32110601_75_dialog_content = "Hmm?",
  ui_story_32110601_76_dialog_content = "Setelah kamu meninggalkan Northland, daripada mengurung diri di kamar, kamu memilih untuk berjalan-jalan di luar.",
  ui_story_32110601_77_dialog_content = "Kamu pergi keluar untuk melihat dunia yang membuat mereka begitu penasaran dan ingin menjelajah.",
  ui_story_32110601_78_dialog_content = "Hargai masa kini dan langit akan selalu cerah.",
  ui_story_32110601_79_dialog_content = "Heh, apakah itu lidah perakmu yang bekerja lagi...? Kamu memang memiliki bakat dalam berbicara.",
  ui_story_32110601_80_dialog_content = "Sayangnya, sepertinya cuaca tidak akan cerah hari ini, terlepas dari seberapa lancar bicaramu.",
  ui_story_32110601_81_dialog_content = "<color=#e8d9bb>Angin lembut bertiup, perlahan menyebabkan awan yang gelisah menghilang secepat mereka terbentuk.</color>",
  ui_story_32110601_82_dialog_content = "<color=#e8d9bb>Sinar matahari menembus awan yang menekan dan menerangi pantai.</color>",
  ui_story_32110601_83_dialog_content = "Aha! Sepertinya hujan memang benar-benar mulai dan berhenti sesuai perintahmu...",
  ui_story_32110601_84_dialog_content = "Hmm, sepertinya saya salah... Apakah mungkin kamu bisa mengendalikan cuaca dengan Luminatics?",
  ui_story_32110601_85_dialog_content = "Caelestite tak bisa menggunakan Lumina.",
  ui_story_32110601_86_dialog_content = "Kalau kamu merasa hujan itu menyenangkan, jalan-jalan di pantai akan membuatmu terkesima! Kamu belum mencobanya, kan?",
  ui_story_32110601_87_dialog_content = "aku belum...",
  ui_story_32110601_88_dialog_content = "Baiklah, dalam hal itu, ayo pergi.",
  ui_story_32110601_89_option_content = "Pegang tangan Zarya",
  ui_story_32110601_90_dialog_content = "Angin laut yang bertiup melalui langit biru cerah setelah hujan sangat lembut...",
  ui_story_32110601_91_dialog_content = "Suara sepatuku menggesek pasir pantai... Aku suka suara ini.",
  ui_story_32110601_92_dialog_content = "Apakah saudariku dan yang lainnya juga mengalami adegan yang sama seperti ini?",
  ui_story_32110601_93_dialog_content = "Sudah seratus tahun berlalu sejak kita membuat janji itu.",
  ui_story_32110601_94_dialog_content = "Apakah mungkin mereka pernah datang ke pantai ini sebelumnya?",
  ui_story_32110601_95_option_content = "Ya, sangat mungkin.",
  ui_story_32110601_96_dialog_content = "Saya yakin mereka pasti datang ke pantai ini.",
  ui_story_32110601_97_dialog_content = "Mereka pasti juga merasakan angin laut yang lembut setelah hujan, dan menghirup udara segar dari lautan ini.",
  ui_story_32110601_98_dialog_content = "Mereka mungkin juga mengunjungi banyak tempat lain.",
  ui_story_32110601_99_dialog_content = "Berjalanlah di jejak langkah mereka dan saksikan dunia luar yang pernah mereka jelajahi.",
  ui_story_32110601_100_dialog_content = "Lagipula, kamu juga cukup menyukai dunia luar.",
  ui_story_32110601_101_dialog_content = "Ya, aku suka.",
  ui_story_32110601_102_option_content = "Mungkin sebelumnya mereka tidak ada di sini.",
  ui_story_32110601_103_dialog_content = "Mereka tidak pernah datang ke sini...?",
  ui_story_32110601_104_dialog_content = "Tapi justru karena mereka tidak datang ke sini, Anda perlu mengalami dunia luar untuk menggantikan tempat mereka.",
  ui_story_32110601_105_dialog_content = "Anda telah melihat apa yang mereka minati dan mencapai jenis kehidupan yang mereka inginkan. Hal itu membuat hati Anda semakin dekat satu sama lain.",
  ui_story_32110601_106_dialog_content = "Selain itu, kamu juga sangat suka tempat ini.",
  ui_story_32110601_107_dialog_content = "Ya, aku suka.",
  ui_story_32110601_108_dialog_content = "Tidak peduli apakah Alina dan Ayah di sini atau tidak, aku akan tetap bertahan di jalanku.",
  ui_story_32110601_109_dialog_content = "Setelah mengalami lebih banyak hal di dunia luar, aku akan kembali ke Northland bersamamu dan berbagi semua yang telah aku lihat dan dengar dengan semua orang.",
  ui_story_32110601_110_dialog_content = "Maju ke dunia yang tidak diketahui... Mungkin itulah mengapa Alina membuat janji itu denganmu.",
  ui_story_32110601_111_dialog_content = "Ingat masa lalu, hargai masa kini, dan nantikan masa depan. Itulah yang perlu kamu lakukan.",
  ui_story_32110601_112_dialog_content = "Omong-omong, aku merasa kamu melupakan sesuatu yang sangat penting.",
  ui_story_32110601_113_dialog_content = "Hah? Aku?",
  ui_story_32110601_114_dialog_content = "Tidak ada komentar tentang pakaian baruku?",
  ui_story_32110601_115_dialog_content = "Oh...",
  ui_story_32110601_116_dialog_content = "Y-Yah... kamu terlihat bagus dalam apapun yang kamu kenakan, jadi aku tidak berpikir perlu mengatakan apa-apa, haha...",
  ui_story_32110601_117_dialog_content = "Jangan kira kau bisa menutupi mataku.",
  ui_story_32110601_118_dialog_content = "Tapi terima kasih, karena menemaniku ke sini.",
  ui_story_32110601_119_dialog_content = "Dan terima kasih telah meluangkan waktu untuk mendengarkan aku bercerita tentang masa lalu.",
  ui_story_32110601_120_dialog_content = "Aku akan terus menjelajahi dunia dan menyaksikan tempat-tempat indah yang belum diketahui.",
  ui_story_32110601_121_dialog_content = "Aku berjanji—aku tak akan pernah mengecewakanmu atau saudara perempuanku."
}
